mapper.select:
SELECT p.*, u.nickname, u.avatar, c.name as category_name FROM t_post p LEFT JOIN t_user u ON p.user_id = u.id LEFT JOIN t_category c ON p.category_id = c.id WHERE p.deleted = 0 AND p.status = 1
AND p.category_id = #{categoryId}
AND p.type = #{type}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.create_time DESC
